"""Fetch public preset imagery, resize bounded offline thumbnails, retain provenance.
Run explicitly when updating presets; normal HTML builds never need the network.
"""
import base64, concurrent.futures, hashlib, io, json, pathlib, re, urllib.request
from PIL import Image
ROOT=pathlib.Path(__file__).resolve().parents[1]
CACHE=ROOT/'.cache/avatar-presets';CACHE.mkdir(parents=True,exist_ok=True)
def fetch(url):
    return urllib.request.urlopen(urllib.request.Request(url,headers={'User-Agent':'GodPower-Classroom/3.0 (offline avatar preset source audit)'}),timeout=25).read()
html=fetch('https://www.smashbros.com/en_US/fighter/index.html').decode()
keys=sorted(set(re.findall(r'hero__item-link-wrap ([a-z_]+)',html)))
alias={'mario':'马力欧','fox':'火狐','kirby':'卡比','pikachu':'皮卡丘','luigi':'路易吉','link':'林克','zelda':'塞尔达','yoshi':'耀西','donkey_kong':'森喜刚','peach':'桃花公主','koopa':'酷霸王','sonic':'索尼克','purin':'胖丁','mewtwo':'超梦','samus':'萨姆斯','daisy':'黛西','pichu':'皮丘','lucario':'路卡利欧'}
jobs=[{'id':'smash-'+k,'name':alias.get(k,k.replace('_',' ').title()),'category':'任天堂与大乱斗','image':'https://www.smashbros.com/assets_v2/img/fighter/thumb_a/'+k+'.png','source':'https://www.smashbros.com/en_US/fighter/index.html','license':'任天堂及对应角色权利人版权；官方公开宣传图，未声明自由许可'} for k in keys]
for category,pages in [('现代政治人物',[('习近平','Xi_Jinping'),('胡锦涛','Hu_Jintao'),('邓小平','Deng_Xiaoping'),('毛泽东','Mao_Zedong'),('江泽民','Jiang_Zemin'),('周恩来','Zhou_Enlai'),('林彪','Lin_Biao'),('王洪文','Wang_Hongwen'),('赵紫阳','Zhao_Ziyang')]),('近代政治人物',[('孙中山','Sun_Yat-sen'),('蒋介石','Chiang_Kai-shek'),('汪精卫','Wang_Jingwei'),('袁世凯','Yuan_Shikai'),('李鸿章','Li_Hongzhang'),('黄兴','Huang_Xing')]),('花草',[('玫瑰','Rose'),('向日葵','Helianthus_annuus'),('荷花','Nelumbo_nucifera'),('郁金香','Tulip'),('蒲公英','Taraxacum'),('薰衣草','Lavandula'),('竹子','Bamboo'),('仙人掌','Cactus')]),('岩石',[('花岗岩','Granite'),('玄武岩','Basalt'),('大理石','Marble'),('黑曜石','Obsidian'),('石英','Quartz'),('紫水晶','Amethyst'),('砂岩','Sandstone'),('板岩','Slate')])]:
    jobs.extend({'id':'wiki-'+page.lower(),'name':name,'category':category,'page':page,'source':'https://en.wikipedia.org/wiki/'+page,'license':'照片许可依原始文件说明页；百科文字许可不等同照片许可'} for name,page in pages)
def process(job):
    try:
        j=dict(job)
        if 'page' in j:
            summary=json.loads(fetch('https://en.wikipedia.org/api/rest_v1/page/summary/'+j.pop('page')))
            j['image']=summary.get('thumbnail',{}).get('source')
            if not j['image']: raise ValueError('source page has no thumbnail')
        raw=fetch(j['image']);original=Image.open(io.BytesIO(raw));original.thumbnail((160,160))
        out=Image.new('RGBA',(160,160),(247,250,248,255));out.alpha_composite(original.convert('RGBA'),((160-original.width)//2,(160-original.height)//2))
        stream=io.BytesIO();out.save(stream,format='WEBP',quality=82,method=6);data=stream.getvalue()
        j['sourceSha256']=hashlib.sha256(raw).hexdigest();j['sha256']=hashlib.sha256(data).hexdigest();j['bytes']=len(data)
        j['dataUrl']='data:image/webp;base64,'+base64.b64encode(data).decode()
        return j,None
    except Exception as e: return None,{'id':job['id'],'name':job['name'],'source':job['source'],'error':str(e)}
with concurrent.futures.ThreadPoolExecutor(max_workers=6) as pool: results=list(pool.map(process,jobs))
categories=['花草','岩石','近代政治人物','现代政治人物','任天堂与大乱斗']
items=sorted([v for v,e in results if v],key=lambda j:categories.index(j['category']));missing=[e for v,e in results if e]
(ROOT/'src/resources/avatar-presets.js').write_text('/* Offline presets; generated by scripts/build-avatar-presets.py. */\nconst AvatarPresetCatalog = '+json.dumps({'schemaVersion':1,'categories':categories,'items':items},ensure_ascii=False,separators=(',',':'))+';\n')
provenance={'schemaVersion':1,'sourceRosterCount':len(keys),'items':[{k:v for k,v in j.items() if k!='dataUrl'} for j in items],'missing':missing}
(ROOT/'docs/AVATAR_PRESET_SOURCES.json').write_text(json.dumps(provenance,ensure_ascii=False,indent=2)+'\n')
print(json.dumps({'downloaded':len(items),'missing':missing,'thumbnailBytes':sum(j['bytes'] for j in items)},ensure_ascii=False))
